package com.example.ava.esphome.tts

/**
 * Speaks text on the device, as an alternative to playing the TTS audio
 * generated by Home Assistant.
 */
interface TextSpeaker : AutoCloseable {
    /**
     * Speaks [text] at the given [volume]. [onCompletion] is called when speech
     * finishes or fails, but not when it is stopped by [stop].
     */
    suspend fun speak(text: String, volume: Float, onCompletion: () -> Unit = {})

    /**
     * Stops any current speech.
     */
    fun stop()
}
